implicit.specification:
schema_version: '1.0'
domain: TEST
keys: [ID]
input: {SRC: {path: input.csv, types: {V: int}}}
output: {path: result.csv, columns: [ID, VALUE]}
columns:
  - {name: ID, type: str, derivation: SRC.ID}
  - name: VALUE
    type: int
    derivation:
      case:
        - when: "SRC.V > 0"
          then: {literal: 7}
        - when: 'FALSE'
          then: SRC.BAD
        - otherwise: {literal: 8}

